16	const AUDIO_WRITERS = [
17	  // `forWriting:` only — `AVAudioFile(forReading:)` is a legitimate way to load
18	  // a bundled sound asset and isn't persistence, so it's deliberately not banned.
19	  [/\bAVAudioFile\s*\(\s*forWriting\b/, 'AVAudioFile(forWriting:)'],
20	  [/\bAVAudioRecorder\s*\(/, 'AVAudioRecorder'],
21	  [/\bExtAudioFileCreateWithURL\s*\(/, 'ExtAudioFileCreateWithURL'],
22	  [/\bAudioFileCreateWithURL\s*\(/, 'AudioFileCreateWithURL'],
23	];
