27	const rule = {
28	  id: 'on-device-privacy/no-audio-persistence',
29	  severity: 'blocking',
30	  description: 'No on-disk audio-writing API in the always-on capture path (mac/Sources/)',
31	  doc: '.claudinite/local/packs/on-device-privacy/RULES.md',
32	  why: 'the product promise is that only derived metadata is kept and no audio is stored — a file-writing audio API in the capture path is how that promise breaks',
33	
34	  run(ctx) {
35	    const out = [];
36	    for (const file of ctx.files.filter(inScope)) {
37	      const text = ctx.read(file);
38	      if (text === null) continue;
39	      const lines = text.split('\n');
40	      for (let i = 0; i < lines.length; i += 1) {
41	        for (const [pattern, what] of AUDIO_WRITERS) {
42	          if (!pattern.test(lines[i])) continue;
43	          out.push({
44	            rule: rule.id,
45	            severity: rule.severity,
46	            file,
47	            line: i + 1,
