4	/// Appends laugh events to a JSONL log under
5	/// `~/Library/Application Support/LaughCounter/laughs.jsonl`.
6	///
7	/// Deliberately greppable. Fields are written in a **fixed
8	/// order** every line (`start_iso, label, start, end, peak, duration, mean,
9	/// source`, then `type`/`context` when present) so the log diffs cleanly and is
10	/// easy to eyeball — `JSONSerialization` can't guarantee key order, so we render
11	/// the JSON ourselves. Confidence values are rounded (they carry no meaning past a
12	/// couple of decimals). No audio is stored — only metadata.
13	final class LaughStore {
14	    private let directory: URL
15	    let fileURL: URL
16	
17	    init() {
18	        let base = FileManager.default.urls(for: .applicationSupportDirectory,
19	                                            in: .userDomainMask)[0]
20	        directory = base.appendingPathComponent("LaughCounter", isDirectory: true)
21	        try? FileManager.default.createDirectory(at: directory,
22	                                                 withIntermediateDirectories: true)
23	        fileURL = directory.appendingPathComponent("laughs.jsonl")
24	    }
