26	    /// Log a detected laugh.
27	    func append(_ event: LaughEvent, source: String = "mic", label: String = "auto") {
28	        var fields: [(String, JSON)] = [
29	            ("start_iso", .str(Self.iso(event.start))),
30	            ("label", .str(label)),
31	            ("start", .num(round3(event.start))),
32	            ("end", .num(round3(event.end))),
33	            ("peak", .num(round2(event.peak))),
34	            ("duration", .num(round2(event.duration))),
35	            ("mean", .num(round2(event.mean))),
36	            ("source", .str(source)),
37	            ("origin", .str(event.origin)),
38	            ("tv_signal", .num(round2(event.tvSignal))),
39	            ("origin_reason", .str(event.originReason)),
40	        ]
41	        if !event.type.isEmpty {
42	            fields.append(("type", .str(event.type)))
43	        }
44	        if !event.context.isEmpty {
45	            fields.append(("context", .arr(event.context.map { c in
46	                JSON.obj([("label", .str(c.label)), ("confidence", .num(round2(c.confidence)))])
47	            })))
48	        }
49	        write(JSON.obj(fields))
50	    }
