52	    /// Log a laugh you told us we missed. `source` distinguishes the spoken
53	    /// command (`"voice"`) from a menu/keyboard click (`"button"`).
54	    func appendMissed(source: String = "voice") {
55	        let now = Date().timeIntervalSince1970
56	        // A miss you reported is, by definition, you.
57	        append(LaughEvent(start: now - 0.5, end: now, duration: 0.5,
58	                          peak: 0, mean: 0, type: "", context: [],
59	                          origin: "me", originReason: "you reported it", tvSignal: 0),
60	               source: source, label: "missed")
61	    }
