64	    /// ("me" or "tv") to count just that bucket; omit for the total.
65	    func todayCount(origin: String? = nil) -> Int {
66	        guard let content = try? String(contentsOf: fileURL, encoding: .utf8) else { return 0 }
67	        let calendar = Calendar.current
68	        var count = 0
69	        for line in content.split(separator: "\n") {
70	            guard let data = line.data(using: .utf8),
71	                  let obj = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
72	                  let start = obj["start"] as? Double else { continue }
73	            // Candidates (sub-threshold, logged for alignment) and rejects don't count.
74	            if let label = obj["label"] as? String, label == "rejected" || label == "candidate" {
75	                continue
76	            }
