92	    private func write(_ json: JSON) {
93	        let line = json.encoded() + "\n"
94	        guard let bytes = line.data(using: .utf8) else { return }
95	        if let handle = try? FileHandle(forWritingTo: fileURL) {
96	            defer { try? handle.close() }
