114	/// A minimal ordered-JSON value, so object keys serialise in insertion order
115	/// (unlike `[String: Any]` + `JSONSerialization`).
116	private indirect enum JSON {
117	    case str(String)
118	    case num(Double)
119	    case obj([(String, JSON)])
120	    case arr([JSON])
121	
122	    func encoded() -> String {
123	        switch self {
124	        case .str(let s): return JSON.encodeString(s)
125	        case .num(let d): return JSON.encodeNumber(d)
126	        case .obj(let pairs):
127	            return "{" + pairs.map { "\(JSON.encodeString($0.0)):\($0.1.encoded())" }
128	                .joined(separator: ",") + "}"
129	        case .arr(let items):
130	            return "[" + items.map { $0.encoded() }.joined(separator: ",") + "]"
131	        }
132	    }
133	
134	    private static func encodeNumber(_ d: Double) -> String {
135	        guard d.isFinite else { return "0" }
136	        // Whole numbers as integers (0 not 0.0); Swift's String(Double) already
137	        // gives the shortest round-trippable form for the rest (0.63, not 0.6300…).
138	        if d == d.rounded() && abs(d) < 1e15 { return String(Int64(d)) }
139	        return String(d)
140	    }
141	
142	    private static func encodeString(_ s: String) -> String {
143	        var out = "\""
144	        for scalar in s.unicodeScalars {
145	            switch scalar {
146	            case "\"": out += "\\\""
147	            case "\\": out += "\\\\"
148	            case "\n": out += "\\n"
149	            case "\r": out += "\\r"
150	            case "\t": out += "\\t"
151	            default:
152	                if scalar.value < 0x20 {
153	                    out += String(format: "\\u%04x", scalar.value)
154	                } else {
155	                    out.unicodeScalars.append(scalar)
156	                }
157	            }
158	        }
159	        return out + "\""
160	    }
161	}
